  22 // NexusDetector handles Sonatype Nexus Repository Manager group repositories.
  23 // Two URL formats are supported:
  24 //  1. Path-based:   https://nexus.example.com/repository/docker-group
  25 //  2. Subdomain:    nexus-docker-group.example.com  (requires info.ManagementURL)
  26 //
  27 // Which one applies is read from the URL. Whether this detector runs at all is
  28 // not: that is the declared provider's decision (§3.8, decision F).
  29 type NexusDetector struct{}
  30 
  31 // maxNexusResponse bounds what one Nexus reply may take in memory. The replies
  32 // are small JSON documents (a repository and the names of its members); the
  33 // figure follows the reasoning of the catalog page cap and is not measured.
  34 const maxNexusResponse = 1 << 20
  35 
  36 // errEmptyReply and errNoRepositoryType mark a 200 reply that is not a
  37 // repository document. Both fail the discovery: reading either as "not a group"
  38 // would be cached (D23) and erase the members last known.
  39 var (
  40     errEmptyReply       = errors.New("empty reply")
  41     errNoRepositoryType = errors.New("reply names no repository type")
  42 )
  43 
  44 // nexusHTTPClient refuses a redirect to another origin, so the account of the
  45 // registry is never sent to a host it was not given for.
  46 var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second, CheckRedirect: oci.RefuseOffOriginRedirect}
  47 
  48 // Provider returns the provider this detector serves.
  49 func (n *NexusDetector) Provider() string { return ProviderNexus }
  50 
  51 // DetectGroup calls the Nexus REST API to determine whether the registry points
  52 // to a group repository and, if so, returns its member repositories.
  53 //
  54 // Returns nil, nil when the manager answered and the repository is not a group,
  55 // and an error when it could not be asked. Those two are not the same thing:
  56 // the caller caches the first and must not cache the second, or one unreachable
  57 // minute erases what was last known (D23).
  58 func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
  59     // Resolve which URL to use for the Nexus API call.
  60     apiBase := info.ManagementURL
  61     if apiBase == "" {
  62         apiBase = info.URL
  63     }
  64 
  65     host, repoName, err := parseNexusURL(apiBase)
  66     if err != nil {
  67         // Not an error: a URL that is not a Nexus repository path is a settled
  68         // answer, not a failure to reach one.
  69         // The cause only: a URL that does not parse may hold a password, and
  70         // url.Error repeats it whole.
  71         var ue *url.Error
  72         if errors.As(err, &ue) {
  73             err = ue.Err
  74         }
  75         log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
  76         return nil, nil
  77     }
  78 
  79     hasAuth := info.Username != "" && info.Password != ""
  80     log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
  81 
  82     // Step 1: generic endpoint — confirms this repo is a group, gets its format,
  83     // and may already include memberNames in the attributes field (no admin privilege needed).
  84     repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
  85     if err != nil {
  86         return nil, err
  87     }
  88     if repoType != "group" {
  89         return nil, nil
  90     }
  91 
  92     if len(members) > 0 {
  93         log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
  94         return members, nil
  95     }
  96 
  97     // Step 2: format-specific endpoint — requires nx-repository-admin privilege
  98     // but returns memberNames reliably on Nexus instances that support it.
  99     members = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
 100     log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
 101     return members, nil
 102 }
