 151 // fetchGroupMembers calls the format-specific group endpoint which reliably
 152 // includes memberNames: GET /v1/repositories/{format}/group/{name}
 153 // Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
 154 func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
 155     if format == "" {
 156         format = "docker"
 157     }
 158     endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
 159     body, err := n.nexusGET(ctx, endpoint, info)
 160     if err != nil {
 161         // When auth is present but the request fails, retry anonymously.
 162         // Some Nexus instances allow anonymous read of the group admin endpoint.
 163         // A refused redirect to another origin is not such a failure: the
 164         // detection stops there (DEVDESK-412), no silent anonymous retry.
 165         if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
 166             anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
 167             body, err = n.nexusGET(ctx, endpoint, anonInfo)
 168         }
 169     }
 170     if errors.Is(err, oci.ErrOffOriginRedirect) {
 171         // The advice below is for an account Nexus refused, not for this.
 172         log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
 173         return nil
 174     }
 175     if err != nil {
 176         log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
 177         return nil
 178     }
 179     var result struct {
 180         Group struct {
 181             MemberNames []string `json:"memberNames"`
 182         } `json:"group"`
 183     }
 184     if err := json.Unmarshal(body, &result); err != nil {
 185         return nil
 186     }
 187     return memberList(info.URL, result.Group.MemberNames)
 188 }
