 204 // memberAddress decides how one member of a group is reached, from the URL the
 205 // group itself is pulled from.
 206 //
 207 // A group written as a path prefix — `host/repository/<group>` — is an instance
 208 // serving its Docker repositories that way, so its members are reached the same
 209 // way: the host, with the member's name in front of the repository. That pair is
 210 // consistent by construction, because browse and pull build the same path from
 211 // it.
 212 //
 213 // Anything else is a connector of the group's own — a dedicated port, a
 214 // subdomain — and says nothing about a member. Which of those a repository
 215 // answers on is a setting on that repository (`docker.httpPort`,
 216 // `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
 217 // refused to an ordinary pull account. So nothing is claimed: the member is
 218 // offered at the group's own address with no prefix, which browses to nothing
 219 // visibly rather than pulling to nothing plausibly (§3.18).
 220 func memberAddress(dockerURL, memberName string) (url, prefix string) {
 221     host, _, err := parseNexusURL(dockerURL)
 222     if err != nil {
 223         return dockerURL, ""
 224     }
 225     // parseNexusURL supplies https:// for a URL written without a scheme. The
 226     // group's own spelling is what the rest of the application is keyed on, so
 227     // it is kept rather than normalised here.
 228     if !strings.Contains(strings.ToLower(dockerURL), "://") {
 229         host = strings.TrimPrefix(host, "https://")
 230     }
 231     return host, memberName
 232 }
