 234 // nexusGET performs an authenticated GET and returns the response body. A status
 235 // other than 200 is a *oci.StatusError from the management API: the code only, no
 236 // status line, body or header. A context error stays a context error.
 237 func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
 238     req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
 239     if err != nil {
 240         return nil, err
 241     }
 242     if info.Username != "" && info.Password != "" {
 243         req.SetBasicAuth(info.Username, info.Password)
 244     }
 245     resp, err := nexusHTTPClient.Do(req)
 246     if err != nil {
 247         // A refused redirect comes back without the URL it pointed to, which
 248         // may be signed.
 249         return nil, oci.StripRedirectTarget(err)
 250     }
 251     defer func() { _ = resp.Body.Close() }()
 252     if resp.StatusCode != http.StatusOK {
 253         return nil, &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
 254     }
 255     body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
 256     if err != nil {
 257         // Which error net/http gives a body cut by a cancel varies: report the
 258         // context's own.
 259         if ctxErr := ctx.Err(); ctxErr != nil {
 260             return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
 261         }
 262         return nil, fmt.Errorf("read Nexus response: %w", err)
 263     }
 264     return body, nil
 265 }
